# -*- coding: utf-8 -*-
# ③-01 fast：纯 Python 编码检测 + frontmatter 标注（不靠 file 子进程，防沙箱拖慢）
# 用法：python3 01b_txt_fast.py            # 干跑，打印报告
#       python3 01b_txt_fast.py --apply   # 落地：转码写 .u8 副本（原文件保留，只增不删）
import os, re, sys, glob, json

VAULT = os.path.expanduser('~/泓记')
APPLY = '--apply' in sys.argv

PLAT = {
    '淘宝天猫': re.compile(r'taobao\.com|tmall\.com|淘宝|天猫', re.I),
    '京东':     re.compile(r'jd\.com|京东', re.I),
    '拼多多':   re.compile(r'pinduoduo\.com|yangkeduo|拼多多', re.I),
    '抖店':     re.compile(r'douyin|抖音|抖店|jinritemai', re.I),
    '小红书':   re.compile(r'xiaohongshu|xhslink|小红书', re.I),
}
TABLE_HINT = re.compile(r'(商品|SKU|销量|库存|单价|订单|店铺)')

def detect_encoding(path):
    """返回 (label, readable_as_utf8, used_enc)。纯 Python，不碰 file。"""
    try:
        raw = open(path, 'rb').read()
    except OSError:
        return ('unreadable', False, None)
    if not raw:
        return ('empty', True, 'utf-8')
    # 尝试 UTF-8
    try:
        raw.decode('utf-8')
        # 再细判：纯 ASCII
        try:
            raw.decode('ascii'); return ('us-ascii', True, 'utf-8')
        except UnicodeDecodeError:
            return ('utf-8', True, 'utf-8')
    except UnicodeDecodeError:
        pass
    # 非 UTF-8：尝试 GB18030（覆盖 GBK）
    try:
        raw.decode('gb18030'); return ('gb18030(GBK)', False, 'gb18030')
    except UnicodeDecodeError:
        pass
    # 兜底
    return ('binary/unknown', False, 'gb18030-replace')

def classify(text):
    for name, rx in PLAT.items():
        if rx.search(text):
            return name
    return None

def main():
    files = [p for p in glob.glob(os.path.join(VAULT, '**', '*.txt'), recursive=True)
             if '/40_归档/' not in p]
    by_enc = {}
    rows = []
    for p in files:
        label, utf8ok, used = detect_encoding(p)
        by_enc[label] = by_enc.get(label, 0) + 1
        rel = os.path.relpath(p, VAULT)
        text = ''
        if utf8ok:
            text = open(p, encoding='utf-8').read()
        else:
            try:
                text = open(p, encoding='gb18030').read()
            except Exception:
                text = open(p, encoding='gb18030', errors='replace').read()
        plat = classify(text)
        is_table = bool(TABLE_HINT.search(text)) and plat is not None
        fm = re.search(r'(20\d{2})[-_.](\d{2})[-_.](\d{2})', os.path.basename(p))
        date = ('%s-%s-%s' % (fm.group(1), fm.group(2), fm.group(3))) if fm else '未知'
        if utf8ok:
            action = 'skip(utf8)'
        elif plat:
            action = 'convert→50_数据/%s' % plat
        else:
            action = 'convert→00_收件箱/_待人工(不猜平台)'
        rows.append({'rel': rel, 'enc': label, 'plat': plat or '-', 'table': is_table,
                     'date': date, 'action': action, 'need_conv': not utf8ok})
    need = sum(1 for r in rows if r['need_conv'])
    ecom = sum(1 for r in rows if r['plat'] != '-' and r['table'])
    manual = sum(1 for r in rows if r['plat'] == '-' )
    print('== ③-01 fast 编码归一（%s）==' % ('APPLY' if APPLY else 'DRY-RUN'))
    print('活区 txt 总数: %d' % len(rows))
    print('编码分布:', json.dumps(by_enc, ensure_ascii=False))
    print('需转码(非utf8): %d | 可进50_数据(平台+表格): %d | 待人工(裸/无平台): %d' % (need, ecom, manual))
    print('== 需转码的逐条（前 30）==')
    for r in [x for x in rows if x['need_conv']][:30]:
        print('  %s | %-16s | 平台=%s | 表=%s | %s' % (r['rel'][:50], r['enc'], r['plat'], r['table'], r['action']))
    if APPLY:
        print('\n[APPLY] 写 .u8 转码副本（原文件保留）……')
        n = 0
        for r in rows:
            if not r['need_conv']:
                continue
            try:
                txt = open(os.path.join(VAULT, r['rel']), encoding='gb18030').read()
            except Exception:
                txt = open(os.path.join(VAULT, r['rel']), encoding='gb18030', errors='replace').read()
            out = os.path.join(VAULT, r['rel']) + '.u8'
            open(out, 'w', encoding='utf-8').write(txt)
            n += 1
        print('完成，转码 %d 份 .u8 副本。' % n)
    else:
        print('\n（DRY-RUN 未改文件；确认无误 Terminal 里加 --apply 落地）')

if __name__ == '__main__':
    main()
